import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "frames"))

from model import load_payload
from transform import transform


class TestFrames(unittest.TestCase):
    def test_transform_shape_and_basename(self):
        payload = {
            "nodes": [
                {
                    "id": "a",
                    "frames": [
                        {
                            "file": "C:\\dir\\mod.py",
                            "line": 3,
                            "function": "f",
                            "locals": {"k": "x"},
                        }
                    ],
                }
            ]
        }
        contract = {"name": "frames", "inputs": ["x"], "output": "y"}
        result = transform([payload], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "frames")
        fr = result["result"]["frames"]["a"][0]
        self.assertEqual(fr["file"], "mod.py")
        self.assertEqual(fr["line"], 3)
        self.assertEqual(fr["function"], "f")
        self.assertEqual(fr["locals"]["k"], '"x"')

    def test_locals_serialization(self):
        payload = {
            "nodes": [
                {
                    "id": "a",
                    "frames": [
                        {
                            "file": "m.py",
                            "line": 1,
                            "function": "f",
                            "locals": {"b": True, "z": [1, None]},
                        }
                    ],
                }
            ]
        }
        contract = {"name": "frames", "inputs": ["x"], "output": "y"}
        result = transform([payload], contract)
        loc = result["result"]["frames"]["a"][0]["locals"]
        self.assertEqual(loc["b"], "true")
        self.assertEqual(loc["z"], "[1,null]")

    def test_line_must_be_positive_int(self):
        payload = {
            "nodes": [
                {
                    "id": "a",
                    "frames": [
                        {"file": "m.py", "line": 0, "function": "f", "locals": {}}
                    ],
                }
            ]
        }
        contract = {"name": "frames", "inputs": ["x"], "output": "y"}
        with self.assertRaises(ValueError):
            transform([payload], contract)

    def test_load_payload_rejects_nonfinite(self):
        import tempfile
        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as f:
            f.write('{"a": NaN}')
            path = f.name
        try:
            with self.assertRaises(ValueError):
                load_payload(path)
        finally:
            Path(path).unlink()


if __name__ == "__main__":
    unittest.main()

