    chain = []
    seen = set()
    cur = root
    while True:
        if cur in seen:
            raise ValueError("cycle detected")
        seen.add(cur)
        if len(chain) >= 8:
            raise ValueError("chain too long")
        n = node_map[cur]
        chain.append(n)
        cause = n["cause"]
        if cause is not None:
            if cause not in node_map:
                raise ValueError("cause not found")
            cur = cause
            continue
        if not n["suppress_context"] and n["context"] is not None:
            ctx = n["context"]
            if ctx not in node_map:
                raise ValueError("context not found")
            cur = ctx
            continue
        break

    # chain is from root to innermost; reverse to innermost->root
    chain.reverse()
    result = []
    for i, n in enumerate(chain):
        if i == 0:
            link = None
        else:
            prev = chain[i - 1]
            if n["cause"] == prev["id"]:
                link = "cause"
            elif n["context"] == prev["id"]:
