    chain.reverse()
    result = []
    for i, n in enumerate(chain):
        if i == 0:
            link = None
        else:
            prev = chain[i - 1]
            if n["cause"] == prev["id"]:
                link = "cause"
            elif n["context"] == prev["id"]:
